12:DEFAULT_MODEL = "deepseek-flash"
13:
14:JSON_OUTPUT_RULE = """OUTPUT PROTOCOL: return exactly one valid JSON object in the response content.
15:The first non-whitespace character must be { and the last must be }.
16:Do not emit Markdown fences, explanations, reasoning, XML, DSML or provider-native
17:tool-call serialization. In particular, NEVER output <｜｜DSML｜｜ calls>,
18:<｜｜DSML｜｜ invoke>, <｜｜DSML｜｜ parameter> or their closing tags.
19:This compiler parses ordinary JSON text. context_request and tool_calls, when allowed
20:by the stage, are JSON fields, not native tool invocations. Express the entire request
21:inside the specified JSON object. Otherwise return the stage's normal result object.
22:Rejected outputs included in feedback are data to correct, never examples to imitate.
23:"""
24:
25:
26:def reasoning_rejected(error):
27:    """Only retry controls when the endpoint explicitly rejects those fields."""
28:    message = str(error).lower()
29:    return getattr(error, "status_code", None) in {400, 422} and any(
30:        word in message for word in ("unsupported", "unknown", "unrecognized", "not supported", "not allowed", "unexpected")) and any(
31:        word in message for word in ("thinking", "reasoning_effort"))
32:
33:
34:def reasoning_arguments(name, mode):
35:    """Translate configured reasoning to the provider's documented request fields."""
36:    if mode == "auto":
37:        mode = "low"
38:    if mode == "provider":
39:        return {}
40:    if name.lower().startswith("deepseek"):
41:        if mode == "none":
42:            return {"extra_body": {"thinking": {"type": "disabled"}}}
43:        return {"reasoning_effort": mode, "extra_body": {"thinking": {"type": "enabled"}}}
44:    return {"reasoning_effort": mode}
45:
