47:class TextModel:
48:    """Transport for structured stage proposals and file-edit responses."""
49:    def __init__(self, *, json_mode: bool = True) -> None:
50:        """Read compiler/.env and configure the default text model; require API credentials."""
51:        load_dotenv(Path(__file__).resolve().parents[3] / ".env", encoding="utf-8-sig")
52:        self.name = os.getenv("MODEL") or DEFAULT_MODEL
53:        api_key = os.getenv("OPENAI_API_KEY")
54:        if not api_key:
55:            raise ValueError("Set OPENAI_API_KEY in compiler/.env")
56:        try:
57:            self.max_output_tokens = int(os.getenv("MAX_OUTPUT_TOKENS", "320000"))
58:        except ValueError as error:
59:            raise ValueError("MAX_OUTPUT_TOKENS must be a positive integer") from error
60:        if self.max_output_tokens < 1:
61:            raise ValueError("MAX_OUTPUT_TOKENS must be a positive integer")
62:        self.reasoning = os.getenv("MODEL_REASONING", "low").lower()
63:        if self.reasoning not in {"auto", "provider", "none", "low", "high", "max"}:
64:            raise ValueError("MODEL_REASONING must be auto, provider, none, low, high or max")
65:        self._reasoning_supported = True
66:        self.json_mode = json_mode
67:        self._token_parameter = "max_completion_tokens"
68:        self.client = OpenAI(
69:            api_key=api_key,
70:            base_url=os.getenv("OPENAI_BASE_URL") or "https://api.openai.com/v1",
71:            timeout=600, max_retries=2,
72:            http_client=http_client(),
73:        )
74:
75:    def _request(self, **arguments):
76:        """Apply one output budget to JSON calls, with legacy endpoint compatibility."""
77:        while True:
78:            options = dict(arguments)
79:            if not getattr(self, "_reasoning_supported", True):
80:                options.pop("reasoning_effort", None)
81:                options.pop("extra_body", None)
82:            try:
83:                return invoke(self.client, {**options, self._token_parameter: self.max_output_tokens})
84:            except OpenAIError as error:
85:                message = str(error).lower()
86:                rejected = getattr(error, "status_code", None) in {400, 422} and any(
87:                    word in message for word in ("unsupported", "unknown", "unrecognized", "not supported", "not allowed", "unexpected"))
88:                if rejected and self._token_parameter == "max_completion_tokens" and "max_completion_tokens" in message:
89:                    self._token_parameter = "max_tokens"
90:                    continue
91:                if getattr(self, "_reasoning_supported", True) and reasoning_rejected(error):
92:                    self._reasoning_supported = False
93:                    print("Provider rejected reasoning controls; using provider defaults.", flush=True)
94:                    continue
95:                raise
96:
97:    def generate_json(self, instructions: str, payload: dict) -> dict:
98:        """Request JSON using the stage prompt and serialized task data."""
99:        mode = getattr(self, "reasoning", "low")
100:        try:
101:            response = self._request(
102:                model=self.name,
103:                messages=[
104:                    {"role": "system", "content": instructions.rstrip() + "\n" + JSON_OUTPUT_RULE},
105:                    {"role": "user", "content": json.dumps(payload, ensure_ascii=False, separators=(",", ":"))},
106:                ],
107:                **({"response_format": {"type": "json_object"}} if getattr(self, "json_mode", True) else {}),
108:                **reasoning_arguments(self.name, mode),
109:            )
110:        except OpenAIError as error:
111:            raise RuntimeError(f"Text model request failed: {error}") from error
112:        if response.choices and response.choices[0].finish_reason == "length":
113:            raise ValueError(
114:                f"Model output was truncated (finish_reason=length). The output budget is "
115:                f"{self.max_output_tokens} tokens including reasoning; this is not an input-length error. "
116:                "Return a complete JSON object with only necessary changes/tool calls; omit unchanged files. "
117:                "Do not spend the entire budget restating the task.")
118:        if response.choices and getattr(response.choices[0].message, "refusal", None):
119:            raise ValueError(f"Text model refused the request: {response.choices[0].message.refusal}")
120:        if not response.choices or not response.choices[0].message.content:
121:            raise ValueError("Text model returned empty content")
122:        content = response.choices[0].message.content.strip()
123:        return json.loads(content)
